F2 = [['plain 的 Pod cgroup', 'memory.max 64 MiB,cpu.max 10000'], ['heavy 的 Pod cgroup', 'memory.max 184 MiB,cpu.max 35000'], ['heavy 的容器 cgroup', '仍是 64 MiB / 10000']]
F3 = [['quota requests.cpu 500m', '已用 450m'], ['再来 heavy(350m)', 'exceeded quota'], ['再来普通 Pod(100m)', 'exceeded quota'], ['overhead 100 核', 'Pending: Insufficient cpu']]
